1	import { db } from "@/lib/db";
2	import { getCurrentUser } from "@/lib/auth";
3	
4	export const dynamic = "force-dynamic";
5	
6	const MIME: Record<string, string> = {
7	  html: "text/html; charset=utf-8",
8	  css: "text/css; charset=utf-8",
9	  js: "text/javascript; charset=utf-8",
10	  map: "application/json",
11	  json: "application/json",
12	  svg: "image/svg+xml",
13	  txt: "text/plain; charset=utf-8",
14	};
15	
16	const SANDBOX_CSP =
17	  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'";
18	
19	// Serves the DRAFT tree for the live in-editor preview. Owner-only — this is
20	// unpublished work, not a public site.
21	export async function GET(
22	  _req: Request,
23	  { params }: { params: Promise<{ id: string; path?: string[] }> },
24	) {
25	  const user = await getCurrentUser();
26	  if (!user) return new Response("Not signed in.", { status: 401 });
27	
28	  const { id, path } = await params;
29	  const project = await db.project.findFirst({ where: { id, userId: user.id } });
30	  if (!project) return new Response("Not found.", { status: 404 });
31	
32	  const filePath = path && path.length > 0 ? path.join("/") : "index.html";
33	  const file = await db.projectFile.findFirst({
34	    where: { projectId: id, path: filePath, published: false, kind: "build" },
35	  });
36	  if (!file) {
37	    return new Response(
38	      filePath === "index.html"
39	        ? "<!doctype html><html><body style='font:14px sans-serif;color:#888;display:grid;place-items:center;height:100vh'>Nothing built yet — describe what you want on the left.</body></html>"
40	        : "Not found.",
41	      { status: filePath === "index.html" ? 200 : 404, headers: { "Content-Type": "text/html; charset=utf-8" } },
42	    );
43	  }
44	
45	  const ext = filePath.split(".").pop() ?? "";
46	  return new Response(file.content, {
47	    headers: {
48	      "Content-Type": MIME[ext] ?? "application/octet-stream",
49	      "Content-Security-Policy": SANDBOX_CSP,
50	      "Cache-Control": "no-store",
51	    },
52	  });
53	}
