1	import { NextRequest, NextResponse } from "next/server";
2	
3	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
4	
5	// The hostname the admin panel answers on, e.g. "ops-7f3k2q.kodely.me".
6	// When set, /admin is reachable ONLY there and 404s on every other host.
7	// When unset (local dev), /admin behaves as it always did.
8	//
9	// This is obscurity, not authorization. Subdomains are not secret: every TLS
10	// certificate is published to public Certificate Transparency logs, so anyone
11	// can search crt.sh for kodely.me and enumerate this name minutes after the
12	// cert is issued. It raises the cost of drive-by scanning and nothing more.
13	// The real gate is the role check in app/admin/layout.tsx and app/admin/page.tsx,
14	// which stays regardless — Next's own proxy docs are explicit that a proxy must
15	// not be the sole authorization boundary, since Server Functions and route
16	// handlers can bypass matcher coverage.
17	const ADMIN_HOST = process.env.KODELY_ADMIN_HOST?.trim().toLowerCase();
18	
19	// Rewritten to when /admin is requested off the admin host. No route exists
20	// here, so Next renders its ordinary not-found page with a 404 — byte-for-byte
21	// what a genuinely nonexistent path returns. A hand-written 404 body would be
22	// distinguishable from a real miss and would advertise that something is here.
23	const NOWHERE = "/_kodely_nonexistent";
24	
25	// A request to <slug>.kodely.site is rewritten to the internal site-serving
26	// API. Everything on the apex app domain (kodely.me / staging.kodely.me)
27	// passes through untouched.
28	export function proxy(req: NextRequest) {
29	  const host = req.headers.get("host") ?? "";
30	  const bareHost = host.split(":")[0].toLowerCase();
31	  const { pathname } = req.nextUrl;
32	
33	  if (bareHost.endsWith(`.${SITES_BASE}`)) {
34	    const slug = bareHost.slice(0, -(SITES_BASE.length + 1));
35	    if (slug && slug !== "www") {
36	      const url = req.nextUrl.clone();
37	      url.pathname = `/api/site/${slug}${pathname === "/" ? "" : pathname}`;
38	      return NextResponse.rewrite(url);
39	    }
40	  }
41	
42	  if (ADMIN_HOST) {
43	    const onAdminHost = bareHost === ADMIN_HOST;
44	
45	    if (pathname === "/admin" || pathname.startsWith("/admin/")) {
46	      if (!onAdminHost) {
47	        const url = req.nextUrl.clone();
48	        url.pathname = NOWHERE;
49	        return NextResponse.rewrite(url);
50	      }
51	    } else if (onAdminHost && pathname === "/") {
52	      // Landing on the admin host goes straight to the panel rather than the
53	      // marketing site. Everything else on this host still resolves normally —
54	      // /login and /api/auth/* have to work here, because the session cookie
55	      // sets no `domain` and is therefore host-only: a session created on
56	      // kodely.me is never sent to this host. Signing in happens here or the
57	      // panel is unreachable.
58	      const url = req.nextUrl.clone();
59	      url.pathname = "/admin";
60	      return NextResponse.rewrite(url);
61	    }
62	  }
63	
64	  return NextResponse.next();
65	}
66	
67	export const config = {
68	  matcher: ["/((?!_next/static|_next/image|favicon.ico).*)"],
69	};
