1	import { query, type ModelUsage } from "@anthropic-ai/claude-agent-sdk";
2	import { mkdtemp, mkdir, writeFile, readFile, rm } from "node:fs/promises";
3	import { existsSync } from "node:fs";
4	import { tmpdir } from "node:os";
5	import path from "node:path";
6	import { isProtectedPath, type AgentEvent, type FileMap } from "./agent";
7	import { narrateTool } from "./build-narration";
8	import { materializeAssets } from "./assets/materialize";
9	
10	// Alternative generation engine, selected with KODELY_ENGINE=sdk.
11	//
12	// Instead of calling the metered Anthropic API with ANTHROPIC_API_KEY, this
13	// drives the Claude Agent SDK, which authenticates with the subscription that
14	// `claude setup-token` logged in on THIS MACHINE. Nothing is metered, so
15	// nothing is billed per build — the point of running it during the testing
16	// period.
17	//
18	// Two things to keep in view while this is switched on:
19	//
20	// 1. COSTS RECORDED HERE ARE IMPUTED, NOT BILLED. The token counts are real —
21	//    taken from the SDK's own modelUsage — but they are priced against the API
22	//    rate card to answer "what would this build have cost on metered billing?".
23	//    No money moves. That keeps the credit meter, the ledger and the margin
24	//    dashboard behaving exactly as they will on metered billing (so they can be
25	//    tested now), but /admin figures are a model, not a statement. See
26	//    meterUsage() below.
27	//
28	// 2. A Claude subscription is licensed for individual use. Running a private
29	//    testing period on it is one thing; serving real customers' generations
30	//    from it is another. Switch KODELY_ENGINE back to `api` before opening up.
31	//
32	// There is deliberately NO fallback to the API engine on failure: if the SDK
33	// is not authenticated this throws, rather than quietly spending money on the
34	// metered key that the operator asked not to use.
35	
36	// The shared SYSTEM prompt is written for the API engine, which exposes
37	// custom `write_file` / `delete_file` tools. The SDK exposes its own
38	// Read/Write/Edit/Bash/Glob/Grep instead, so that sentence is not just
39	// useless here — it actively breaks generation: the agent announces it is
40	// building, reaches for a tool that does not exist, and the run ends having
41	// written nothing. (That is exactly what happened the first time this engine
42	// ran in prod.)
43	const API_TOOL_CONTRACT =
44	  "Use the write_file and delete_file tools. Always pass the complete final file — there is no patch tool.";
45	
46	// The assets paragraph has the same problem as the tool contract: the shared
47	// prompt tells the agent to call find_assets, which exists only on the API
48	// engine. Here the catalogue is on disk instead (see lib/assets/materialize.ts),
49	// so the instruction has to point at Grep and Read.
50	const API_ASSET_CONTRACT =
51	  "Search the catalogue with the find_assets tool — pass what you need in plain words (\"plumber wrench icon\", \"warm sunset gradient\", \"wave divider\") and paste the source it returns.";
52	
53	const SDK_ASSET_CONTRACT = [
54	  "The catalogue is on disk in this working directory:",
55	  "- `.kodely-assets/INDEX.md` lists every asset — id, name, keywords, and the file holding its source.",
56	  "- Grep INDEX.md for what you need (e.g. `grep -i wrench .kodely-assets/INDEX.md`), then Read the file it names and paste the contents in.",
57	  "Do NOT copy `.kodely-assets` into the site or reference those paths at runtime — they are a reference library, not project files.",
58	].join("\n");
59	
60	// The exact set of tools this engine may use. Enforced by canUseTool below,
61	// which denies anything absent from this list — including tools a future SDK
62	// version might add.
63	//
64	// Bash is NOT here, and that is the whole point: the prompt is untrusted user
65	// input, and shell access on the machine that runs generations is not something
66	// a website request should be able to obtain. The cost is that the agent cannot
67	// delete a file; SDK_TOOL_CONTRACT tells it what to do instead.
68	const SDK_TOOLS = ["Read", "Write", "Edit", "Glob", "Grep"];
69	
70	// Belt and braces: named explicitly so they are stripped from the model's
71	// context rather than merely refused at call time. A tool it never sees is one
72	// it never wastes a turn attempting.
73	const SDK_DENIED_TOOLS = [
74	  "Bash",
75	  "BashOutput",
76	  "KillShell",
77	  "WebFetch",
78	  "WebSearch",
79	  "Task",
80	  "Agent",
81	  "NotebookEdit",
82	  "TodoWrite",
83	];
84	
85	const SDK_TOOL_CONTRACT = [
86	  "You are editing a real checkout on disk in the working directory.",
87	  "- Use Write to create or replace a file, passing the complete final contents.",
88	  "- Use Edit for a targeted change to an existing file.",
