172	/**
173	 * Turn an SDK result into the usage event the charging path expects.
174	 *
175	 * IMPORTANT — what this cost means. On the subscription there is no metered
176	 * per-build charge, so this is an IMPUTED cost: the real tokens this build
177	 * consumed, priced at the API rate card. It is what the build WOULD have cost
178	 * on metered billing, not money that left an account.
179	 *
180	 * That is deliberately more useful than reporting zeros. Zeroed usage made
181	 * every SDK build cost exactly 1 credit (the floor) and flatlined the
182	 * cost/margin dashboard — which is the instrument for the board's "riskiest
183	 * assumption #1", whether infra can beat credit economics. With real token
184	 * counts the credit meter, the ledger and the margin view all behave exactly
185	 * as they will on metered billing, which is what makes them testable now.
186	 *
187	 * `modelUsage` is the field the SDK documents as correct for token accounting:
188	 * it spans the main loop plus subagents and internal calls, where `usage`
189	 * covers only the main loop. It is cumulative per query() call, so it is read
190	 * once from the final result rather than summed across results.
191	 */
192	function meterUsage(message: { modelUsage?: Record<string, ModelUsage> }): {
193	  model: string;
194	  inputTokens: number;
195	  outputTokens: number;
196	  cacheReadTokens: number;
197	  cacheWriteTokens: number;
198	} {
199	  const usage = message.modelUsage ?? {};
200	  const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
201	
202	  // The charging path takes ONE model string plus summed tokens, so attribute
203	  // the build to whichever model produced the most output tokens — output
204	  // dominates cost on every rate in the card. In practice Claude Code runs one
205	  // model for the main loop, so this is usually exact; when a cheap auxiliary
206	  // model also ran, its tokens are still counted, just priced at the main
207	  // model's rate. That errs toward over-billing, never under.
208	  let dominant = "";
209	  let mostOutput = -1;
210	
211	  for (const [model, u] of Object.entries(usage)) {
212	    totals.inputTokens += u.inputTokens ?? 0;
213	    totals.outputTokens += u.outputTokens ?? 0;
214	    totals.cacheReadTokens += u.cacheReadInputTokens ?? 0;
215	    totals.cacheWriteTokens += u.cacheCreationInputTokens ?? 0;
216	    if ((u.outputTokens ?? 0) > mostOutput) {
217	      mostOutput = u.outputTokens ?? 0;
218	      dominant = u.canonicalModel ?? model;
219	    }
220	  }
221	
222	  return {
223	    // No usage at all (a crashed or startup-error result) keeps the old
224	    // self-explaining tag, so a 1-credit build is visibly "no telemetry"
225	    // rather than looking like a genuinely free one.
226	    model: dominant ? toRateKey(dominant) : "claude-agent-sdk-subscription",
227	    ...totals,
228	  };
229	}
