256	async function readFileTree(dir: string, prefix = ""): Promise<FileMap> {
257	  const { readdir } = await import("node:fs/promises");
258	  const out: FileMap = {};
259	  const entries = await readdir(dir, { withFileTypes: true });
260	  for (const e of entries) {
261	    if (e.name === "node_modules" || e.name === ".git" || e.name.startsWith(".")) continue;
262	    const rel = prefix ? `${prefix}/${e.name}` : e.name;
263	    const full = path.join(dir, e.name);
264	    if (e.isDirectory()) Object.assign(out, await readFileTree(full, rel));
265	    else out[rel] = await readFile(full, "utf8");
266	  }
267	  return out;
268	}
