281	export async function* runAgentSdk(
282	  opts: SdkOptions,
283	  systemPrompt: string,
284	): AsyncGenerator<AgentEvent> {
285	  // The SDK edits a real directory rather than calling tools over the wire,
286	  // so the project is materialised to a temp dir and diffed afterwards.
287	  assertSdkCredentials();
288	  const workDir = await mkdtemp(path.join(tmpdir(), "kodely-sdk-"));
289	
290	  try {
291	    await writeFileMap(workDir, opts.files);
292	
293	    // Reference library beside the project. Dot-prefixed so readFileTree()
294	    // below skips it — otherwise every generated site would gain ~460 files.
295	    await materializeAssets(workDir);
296	
297	    let imageNote = "";
298	    if (opts.image) {
299	      const ext = opts.image.mediaType.split("/")[1] ?? "png";
300	      await writeFile(path.join(workDir, `.reference.${ext}`), Buffer.from(opts.image.data, "base64"));
301	      imageNote = `\n\nA reference image was attached to this request — Read the file .reference.${ext} in this directory to see it, then use it as visual/style guidance.`;
302	    }
303	
304	    const historyText = opts.history.length
305	      ? `## Prior conversation on this project\n${opts.history
306	          .map((h) => `${h.role === "user" ? "User" : "You"}: ${h.content}`)
307	          .join("\n\n")}\n\n`
308	      : "";
309	
310	    yield {
311	      type: "status",
312	      text: opts.kind === "create" ? "Building your site…" : "Applying your changes…",
313	    };
314	
315	    for await (const message of query({
316	      prompt: `${historyText}## Current request\n${opts.request}${imageNote}`,
317	      options: {
318	        cwd: workDir,
319	        systemPrompt: adaptPromptForSdk(systemPrompt),
320	        // `allowedTools` is an AUTO-APPROVE list, not a restriction. The SDK's
321	        // own docs say so: "List of tool names that are auto-allowed without
322	        // prompting for permission... To restrict which tools are available,
323	        // use the `tools` option instead."
324	        //
325	        // This code previously listed Bash here believing it was a whitelist.
326	        // It was not: every other tool remained available, and Bash itself was
327	        // pre-approved — so a user's prompt had unrestricted shell on the box
328	        // that runs generations. `cwd` is not a jail.
329	        //
330	        // There is no Options-level `tools` field (that exists only on
331	        // AgentDefinition), so the restriction is enforced two ways:
332	        allowedTools: SDK_TOOLS,
333	        // 1. Removes them from the model's context entirely — it cannot call
334	        //    what it cannot see.
335	        disallowedTools: SDK_DENIED_TOOLS,
336	        // 2. The authoritative gate. A deny-list can only block names we
337	        //    thought of; this allow-list refuses anything not on it, so a tool
338	        //    added by a future SDK version is denied by default rather than
339	        //    silently permitted.
340	        // `updatedInput` is deliberately omitted — passing it REPLACES the
341	        // tool's real input, which would break every call it allows.
342	        canUseTool: async (toolName: string) =>
343	          SDK_TOOLS.includes(toolName)
344	            ? { behavior: "allow" as const }
345	            : {
346	                behavior: "deny" as const,
347	                message: `${toolName} is not available in this environment.`,
348	              },
349	        permissionMode: "acceptEdits",
350	      },
351	    })) {
352	      if (opts.signal?.aborted) break;
353	
354	      if (message.type === "assistant" && message.message?.content) {
355	        for (const block of message.message.content) {
356	          if ("text" in block && block.text) {
357	            yield { type: "text", text: block.text };
358	          } else if (block.type === "tool_use") {
359	            // The only live signal this engine gives. Files are diffed out of
360	            // the working directory AFTER query() finishes, so without this the
361	            // chat sits silent for the whole build and then dumps every file at
362	            // once. Narrating the tool calls is what makes the wait legible.
363	            const line = narrateTool(block.name, (block.input ?? {}) as Record<string, unknown>);
364	            if (line) yield { type: "progress", text: line };
365	          }
366	        }
367	      } else if (message.type === "result") {
368	        yield { type: "usage", ...meterUsage(message) };
369	      }
370	    }
371	
372	    if (opts.signal?.aborted) return;
373	
374	    // Diff the directory back into write/delete events so the caller persists
375	    // exactly what the API engine would have produced.
376	    const after = await readFileTree(workDir);
377	
378	    for (const [p, content] of Object.entries(after)) {
379	      if (p.startsWith(".reference.")) continue;
380	      const rel = safeRelPath(p);
381	      if (!rel) continue;
382	      if (opts.files[p] === content) continue; // unchanged
383	      if (await opts.onWrite(rel, content)) yield { type: "file", path: rel, action: "write" };
384	    }
385	    for (const p of Object.keys(opts.files)) {
386	      if (p in after) continue;
387	      const rel = safeRelPath(p);
388	      if (!rel) continue;
389	      if (await opts.onDelete(rel)) yield { type: "file", path: rel, action: "delete" };
390	    }
391	  } finally {
392	    // On Windows a just-exited child can hold the dir briefly (EBUSY); retry,
393	    // and never let cleanup failure mask a successful generation.
394	    try {
395	      await rm(workDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
396	    } catch {}
397	  }
398	}
