7	// Everything is nested under a single folder named for the slug, the way a
8	// GitHub "Download ZIP" behaves — unzipping into the user's Downloads folder
9	// should produce one project directory, not scatter package.json and src/
10	// across whatever they happened to be sitting in.
11	function entryPath(slug: string, path: string): string {
12	  return `${slug}/${path}`;
13	}
